        /// <summary>
        /// Helper object that stores the services available in this plug-in.
        /// </summary>
        /// <param name="serviceProvider"></param>
        public PluginContext(IServiceProvider serviceProvider)
        {
            if (serviceProvider == null)
            {
                throw new InvalidPluginExecutionException("serviceProvider");
            }
            ServiceProvider = serviceProvider;
            // Obtain the execution context service from the service provider.
            PluginExecutionContext = (IPluginExecutionContext)serviceProvider.GetService(typeof(IPluginExecutionContext));

            // Obtain the tracing service from the service provider.
            //TracingService = new LocalTracingService(serviceProvider);
            TracingService = (ITracingService)serviceProvider.GetService(typeof(ITracingService));
            // Get the notification service from the service provider.
            NotificationService = (IServiceEndpointNotificationService)serviceProvider.GetService(typeof(IServiceEndpointNotificationService));

            // Obtain the organization factory service from the service provider.
            IOrganizationServiceFactory factory = (IOrganizationServiceFactory)serviceProvider.GetService(typeof(IOrganizationServiceFactory));

            // Use the factory to generate the organization service.
            CurrentUserService = factory.CreateOrganizationService(PluginExecutionContext.UserId);

            // Use the factory to generate the organization service.
            SystemUserService = factory.CreateOrganizationService(null);

            if (PluginExecutionContext.InputParameters.Contains("Target")
                && PluginExecutionContext.InputParameters["Target"] is Entity)
            {
                CurrentEntity = (Entity)PluginExecutionContext.InputParameters["Target"];
            }

            if (PluginExecutionContext.InputParameters.Contains("Target")
               && PluginExecutionContext.InputParameters["Target"] is EntityReference)
            {
                CurrentEntityReference = (EntityReference)PluginExecutionContext.InputParameters["Target"];
            }

            currentUserId = this.PluginExecutionContext.UserId;
            CurrentUserEr = new EntityReference("systemuser", this.PluginExecutionContext.UserId);
            lcid = new UserSettingQueryService().GetUserLCID(this.CurrentUserService, currentUserId);
            messageName = this.PluginExecutionContext.MessageName;
        }

