                        var entity = item.Value as Entity;
                        this.Trace($"Plugin {dataName} [{int_index}]-[{item.Key}] Serizlize String:{JsonConvert.SerializeObject(entity.Attributes)}");
                    }
                    else
                    {
                        this.Trace($"Plugin {dataName} [{int_index}]-[{item.Key}] Serizlize String:{JsonConvert.SerializeObject(item.Value)}");
                    }
                    int_index++;
                }
            }
            else
