        /// <summary>
        /// 金额字段是否改变
        /// </summary>
        /// <param name="field"></param>
        /// <returns></returns>
        public bool IsDecimalChanged(string field)
        {
            if (messageName.ToLower() == "create" || messageName.ToLower() == "delete") return true;
            if (!CurrentEntity.Contains(field)) return false;

            var curInitAmount = CurrentEntity.ToDecimal(field);
            var preInitAmount = PreImage.ToDecimal(field);
            return curInitAmount != preInitAmount;
        }

